   230     size_t bytes_read = 0;
   231     size_t remaining = size;
   232     size_t block_count = 0;
   233
   234     *iter = NULL;
   235
   236     while (remaining > 12) {
   237        const uint32_t *local_data = (const uint32_t *)(memory);
   238
   239        if (current == NULL) {
   240           current = calloc(1, sizeof(struct _light_pcapng));
   241           DCHECK_NULLP(current, return block_count);
   242
   243           if (*iter == NULL) {
   244              *iter = current;
   245           }
   246        }
   247        else {
   248           current->next_block = calloc(1, sizeof(struct _light_pcapng));
   249           DCHECK_NULLP(current->next_block, return block_count);
   250
   251           current = current->next_block;
   252        }
   253
   254        current->block_type = *local_data++;
   255        current->block_total_length = *local_data++;
   256        DCHECK_INT(((current->block_total_length % 4) == 0), 0, light_stop);
   257
   258        parse_by_block_type(current, local_data, memory);
   259
   260        // Compute offset and return new link.
   261        // Block total length.
   262        DCHECK_ASSERT((bytes_read = *local_data++), current->block_total_length, light_stop);
   263
   264        bytes_read = current->block_total_length;
   265        remaining -= bytes_read;
   266        memory += bytes_read / sizeof(*memory);
